/* 학습 해설
 * HTB·계층 Token과 대역폭 차용
 * Class별 보장 rate와 여유 대역폭을 빌릴 수 있는 ceiling을 계층으로 관리하려면 부모까지 전송 비용을 반영해야 합니다.
 * HTB는 rate token·ceiling token과 CAN_SEND/MAY_BORROW/CANT_SEND 상태를 관리합니다. 전송 비용을 leaf에서 부모까지 charge하고 서비스 level에 따라 lend·borrow 회계를 구분합니다. Dequeue는 level·priority와 가능한 subtree를 조사하고 credit이 회복될 다음 event로 watchdog을 예약합니다.
 * 격리된 Linux namespace에서 tc htb의 parent·rate·ceil·burst·cburst·prio·quantum과 default 분류를 확인합니다. Parent capacity와 offered load를 함께 계산하고 ceil이 모든 class가 동시에 얻는 보장 rate라고 해석하지 않습니다.
 */
static void htb_charge_class(struct htb_sched *q, struct htb_class *cl,
			     int level, struct sk_buff *skb)
{
	int bytes = qdisc_pkt_len(skb);
	enum htb_cmode old_mode;
	s64 diff;

	while (cl) {
		diff = min_t(s64, q->now - cl->t_c, cl->mbuffer);
		if (cl->level >= level) {
			if (cl->level == level)
				cl->xstats.lends++;
			htb_accnt_tokens(cl, bytes, diff);
		} else {
			cl->xstats.borrows++;
			cl->tokens += diff;	/* we moved t_c; update tokens */
		}
		htb_accnt_ctokens(cl, bytes, diff);
		cl->t_c = q->now;

		old_mode = cl->cmode;
		diff = 0;
		htb_change_class_mode(q, cl, &diff);
		if (old_mode != cl->cmode) {
			if (old_mode != HTB_CAN_SEND)
				htb_safe_rb_erase(&cl->pq_node, &q->hlevel[cl->level].wait_pq);

