/* 학습 해설
 * CAKE·Shaper·Tin·Host와 Flow 격리
 * Bufferbloat를 줄이면서 한 host가 많은 flow를 열어 share를 독점하지 않게 하려면 여러 정책을 결합해야 합니다.
 * CAKE는 전역 shaper 시각, Diffserv tin 선택, flow byte deficit과 선택적인 source/destination host load를 결합합니다. Shaped mode와 unlimited DRR mode는 tin 선택 방식이 다릅니다. Flow에서는 COBALT AQM을 거쳐 packet을 얻고 wire accounting에 따른 비용으로 flow·tin deficit과 다음 전송 시각을 갱신합니다.
 * Linux namespace 또는 실습 router에서 cake bandwidth·diffserv·flow/host isolation·overhead·NAT·ingress 옵션을 확인합니다. Host mapping과 flow hash·wire length 단위가 실제 topology에 맞는지 관찰하고 모든 옵션을 켰다는 것만으로 공정성을 단정하지 않습니다.
 */
static struct sk_buff *cake_dequeue(struct Qdisc *sch)
{
	struct cake_sched_data *q = qdisc_priv(sch);
	struct cake_tin_data *b = &q->tins[q->cur_tin];
	struct cake_host *srchost, *dsthost;
	ktime_t now = ktime_get();
	struct cake_flow *flow;
	struct list_head *head;
	bool first_flow = true;
	struct sk_buff *skb;
	u16 host_load;
	u64 delay;
	u32 len;

begin:
	if (!sch->q.qlen)
		return NULL;

	/* global hard shaper */
	if (ktime_after(q->time_next_packet, now) &&
	    ktime_after(q->failsafe_next_packet, now)) {
		u64 next = min(ktime_to_ns(q->time_next_packet),
			       ktime_to_ns(q->failsafe_next_packet));

		sch->qstats.overlimits++;
		qdisc_watchdog_schedule_ns(&q->watchdog, next);

