/* 학습 해설
 * Ingress·CLSACT와 TCX의 Classifier 연결
 * 수신 packet이나 송신 직전 packet에 분류·action을 적용하는 지점은 저장·전송 순서를 정하는 queue와 구분해야 합니다.
 * Ingress init은 TC_H_INGRESS parent를 검사하고 장치의 TCX entry를 얻어 mini qdisc pair와 classifier block을 연결합니다. Chain head 변경 callback으로 실행 지점과 block을 연결합니다. 같은 파일의 clsact는 ingress·egress hook을 관리하며 FIFO dequeue나 자체 rate bucket으로 packet을 지연시키는 방식이 아닙니다.
 * 격리된 namespace에서 tc clsact와 ingress/egress filter·action을 설정합니다. Classifier 결과·drop·redirect·police와 offload를 구분하고 ingress에서 원격 sender의 이미 전송된 wire 시간을 되돌릴 수 있다고 생각하지 않습니다.
 */
static int ingress_init(struct Qdisc *sch, struct nlattr *opt,
			struct netlink_ext_ack *extack)
{
	struct ingress_sched_data *q = qdisc_priv(sch);
	struct net_device *dev = qdisc_dev(sch);
	struct bpf_mprog_entry *entry;
	bool created;
	int err;

	if (sch->parent != TC_H_INGRESS)
		return -EOPNOTSUPP;

	net_inc_ingress_queue();

	entry = tcx_entry_fetch_or_create(dev, true, &created);
	if (!entry)
		return -ENOMEM;
	tcx_miniq_inc(entry);
	mini_qdisc_pair_init(&q->miniqp, sch, &tcx_entry(entry)->miniq);
	if (created)
		tcx_entry_update(dev, entry, true);

	q->block_info.binder_type = FLOW_BLOCK_BINDER_TYPE_CLSACT_INGRESS;
	q->block_info.chain_head_change = clsact_chain_head_change;
	q->block_info.chain_head_change_priv = &q->miniqp;

