/* 학습 해설
 * LoadPin·Kernel Load의 Superblock 출처 고정
 * 커널 module·firmware 같은 코드나 데이터가 예상한 파일시스템 출처에서 로드되는지 제한할 수 있습니다.
 * LoadPin은 최초 허용된 load 파일의 superblock을 pinned_root로 정합니다. 이후 같은 superblock 또는 신뢰한 dm-verity block device 출처를 검사합니다. Excluded file id는 pinning을 건너뛰고 file이 없는 구형 load API는 enforce 상태에서 EPERM입니다. Enforce가 꺼진 상태의 다른 출처는 기록 후 허용할 수 있습니다.
 * 격리된 VM에서 LoadPin LSM·enforce·exclude id와 trusted verity digest 설정을 확인합니다. 파일 이름·경로 문자열 비교가 아니라 superblock 기반임을 이해하고 쓰기 가능한 pinned filesystem과 unmount의 효과도 읽습니다.
 */
static int loadpin_check(struct file *file, enum kernel_read_file_id id)
{
	struct super_block *load_root;
	const char *origin = kernel_read_file_id_str(id);
	bool first_root_pin = false;
	bool load_root_writable;

	/* If the file id is excluded, ignore the pinning. */
	if ((unsigned int)id < ARRAY_SIZE(ignore_read_file_id) &&
	    ignore_read_file_id[id]) {
		report_load(origin, file, "pinning-excluded");
		return 0;
	}

	/* This handles the older init_module API that has a NULL file. */
	if (!file) {
		if (!enforce) {
			report_load(origin, NULL, "old-api-pinning-ignored");
			return 0;
		}

		report_load(origin, NULL, "old-api-denied");
		return -EPERM;
	}

	load_root = file->f_path.mnt->mnt_sb;

