/* 학습 해설
 * Lockdown·Integrity·Confidentiality 제한 단계
 * Root 권한이 있어도 커널 코드·비밀 상태를 직접 바꾸거나 읽는 경로를 정책으로 제한할 필요가 있습니다.
 * Lockdown은 제한 reason을 enum의 순서와 현재 kernel_locked_down level로 비교합니다. 요청 reason이 현재 level 이하이면 EPERM이고 범위 밖 reason도 거부합니다. Level을 올리는 함수는 현재 이상으로만 강화할 수 있으며 동일·더 낮은 level 요청은 EPERM입니다. Integrity와 confidentiality의 구체 범위는 reason 정의와 호출 지점에서 확인합니다.
 * 격리된 VM에서 config·boot parameter·securityfs lockdown 상태와 실제 security_locked_down 호출 지점을 확인합니다. 일반 DAC root 권한·capability 허용과 이 정책의 거부를 구분하고 이름만으로 모든 kernel 접근을 동일 차단이라고 추정하지 않습니다.
 */
static int lockdown_is_locked_down(enum lockdown_reason what)
{
	if (WARN(what >= LOCKDOWN_CONFIDENTIALITY_MAX,
		 "Invalid lockdown reason"))
		return -EPERM;

	if (kernel_locked_down >= what) {
		if (lockdown_reasons[what])
			pr_notice_ratelimited("Lockdown: %s: %s is restricted; see man kernel_lockdown.7\n",
				  current->comm, lockdown_reasons[what]);
		return -EPERM;
	}

	return 0;
}

static struct security_hook_list lockdown_hooks[] __ro_after_init = {
	LSM_HOOK_INIT(locked_down, lockdown_is_locked_down),
};

static const struct lsm_id lockdown_lsmid = {
	.name = "lockdown",
	.id = LSM_ID_LOCKDOWN,
};

static int __init lockdown_lsm_init(void)

