/* 학습 해설
 * SafeSetID·UID·GID 전환 Allowlist와 실패
 * Setuid capability를 가진 process도 허용된 ID로만 이동하게 하려면 credential 전환의 전체 필드를 검사해야 합니다.
 * SafeSetID는 old real UID에 적용되는 제한 policy가 없으면 이 hook을 통과합니다. 제한이 있으면 new uid·euid·suid·fsuid가 각각 허용되는지 검사합니다. 기존 real/effective/saved ID로의 전환은 허용할 수 있고 새로운 ID는 allowlist를 확인합니다. 위반 시 이 hook은 SIGKILL을 강제하고 EACCES를 반환합니다.
 * 격리된 VM에서 SafeSetID policy와 UID/GID namespace 표현을 확인한 뒤 제한 전환을 시험합니다. 권한을 낮추는 대상 ID도 필요한 allowlist에 포함하고 실제 환경의 관리자 process를 실습 대상으로 쓰지 않습니다.
 */
static int safesetid_task_fix_setuid(struct cred *new,
				     const struct cred *old,
				     int flags)
{

	/* Do nothing if there are no setuid restrictions for our old RUID. */
	if (setid_policy_lookup((kid_t){.uid = old->uid}, INVALID_ID, UID) == SIDPOL_DEFAULT)
		return 0;

	if (id_permitted_for_cred(old, (kid_t){.uid = new->uid}, UID) &&
	    id_permitted_for_cred(old, (kid_t){.uid = new->euid}, UID) &&
	    id_permitted_for_cred(old, (kid_t){.uid = new->suid}, UID) &&
	    id_permitted_for_cred(old, (kid_t){.uid = new->fsuid}, UID))
		return 0;

	/*
	 * Kill this process to avoid potential security vulnerabilities
	 * that could arise from a missing allowlist entry preventing a
	 * privileged process from dropping to a lesser-privileged one.
	 */
	force_sig(SIGKILL);
	return -EACCES;
}

