/* 학습 해설
 * Smack·Subject·Object Label과 Access Bitmask
 * 객체와 실행 주체의 label 관계로 접근을 제어하려면 요구 권한이 허용 권한의 부분집합인지 판단해야 합니다.
 * Smack은 subject/object label의 특별 규칙을 먼저 적용하고 일반 관계는 subject의 rule list에서 may mask를 찾습니다. Requested bits가 may에 모두 포함되어야 합니다. Star subject는 거부하지만 star object는 허용하고 같은 label은 허용하는 등 방향이 다릅니다. Audit와 선택적인 bringup config도 결과 해석에 영향을 줍니다.
 * 격리된 VM에서 Smack label·rule interface와 audit를 확인하고 read/write/execute 요청을 비교합니다. Special label과 unconfined·bringup 모드를 config와 함께 읽고 subject/object를 뒤집어 같은 관계라고 취급하지 않습니다.
 */
int smk_access(struct smack_known *subject, struct smack_known *object,
	       int request, struct smk_audit_info *a)
{
	int may = MAY_NOT;
	int rc = 0;

	/*
	 * Hardcoded comparisons.
	 */
	/*
	 * A star subject can't access any object.
	 */
	if (subject == &smack_known_star) {
		rc = -EACCES;
		goto out_audit;
	}
	/*
	 * An internet object can be accessed by any subject.
	 * Tasks cannot be assigned the internet label.
	 * An internet subject can access any object.
	 */
	if (object == &smack_known_web || subject == &smack_known_web)
		goto out_audit;
	/*
	 * A star object can be accessed by any subject.
	 */

