/* 학습 해설
 * TOMOYO·실행 이력 Domain과 Exec 전환
 * 같은 프로그램이라도 어떤 실행 경로로 도달했는지에 따라 정책 domain을 구분하면 실행 이력에 기반한 접근 제어가 가능합니다.
 * TOMOYO는 exec 대상 pathname을 얻고 aggregator 규칙을 적용한 뒤 execute permission을 검사합니다. 전환 preference·transition control에 따라 keep·child·reset·initialize·parent 등 다음 domain을 계산합니다. 일반 child는 old domain 이름 뒤에 실행 후보를 연결합니다. 목적 domain 할당 실패는 enforcing과 명시적인 전환 조건에 따라 exec 실패가 될 수 있습니다.
 * 격리된 VM에서 TOMOYO domain policy·exception policy·profile mode와 동일 프로그램의 서로 다른 exec 경로를 비교합니다. Learning·permissive·enforcing 및 domain transition failure를 audit와 함께 읽습니다.
 */
int tomoyo_find_next_domain(struct linux_binprm *bprm)
{
	struct tomoyo_domain_info *old_domain = tomoyo_domain();
	struct tomoyo_domain_info *domain = NULL;
	const char *original_name = bprm->filename;
	int retval = -ENOMEM;
	bool reject_on_transition_failure = false;
	const struct tomoyo_path_info *candidate;
	struct tomoyo_path_info exename;
	struct tomoyo_execve *ee = kzalloc(sizeof(*ee), GFP_NOFS);

	if (!ee)
		return -ENOMEM;
	ee->tmp = kzalloc(TOMOYO_EXEC_TMPSIZE, GFP_NOFS);
	if (!ee->tmp) {
		kfree(ee);
		return -ENOMEM;
	}
	/* ee->dump->data is allocated by tomoyo_dump_page(). */
	tomoyo_init_request_info(&ee->r, NULL, TOMOYO_MAC_FILE_EXECUTE);
	ee->r.ee = ee;
	ee->bprm = bprm;
	ee->r.obj = &ee->obj;
	ee->obj.path1 = bprm->file->f_path;
	/* Get symlink's pathname of program. */
	exename.name = tomoyo_realpath_nofollow(original_name);

