/* 학습 해설
 * RAMFS·파일시스템 형식과 구현 계약
 * 가장 단순한 메모리 파일시스템을 읽으면 VFS의 inode·dentry·page cache가 파일 기능을 어떻게 제공하는지 볼 수 있습니다.
 * Ramfs는 별도 disk format 없이 VFS cache 구조로 데이터를 유지합니다. Fill_super는 PAGE_SIZE block·operation table·root directory inode/dentry를 준비합니다. Get_inode는 종류에 따라 일반 파일·directory·symlink operation을 연결하고 mapping을 unevictable로 표시합니다. Backing store로 writeback해 제거하는 일반 disk cache와 다릅니다.
 * 격리된 VM에서 작은 ramfs mount의 file 생성·조회와 unmount 수명을 확인합니다. Tmpfs의 size limit·swap 기능과 같은 정책을 자동으로 기대하지 말고 ramfs의 mount option·memory lifetime을 원본에서 비교합니다.
 */
static int ramfs_fill_super(struct super_block *sb, struct fs_context *fc)
{
	struct ramfs_fs_info *fsi = sb->s_fs_info;
	struct inode *inode;

	sb->s_maxbytes		= MAX_LFS_FILESIZE;
	sb->s_blocksize		= PAGE_SIZE;
	sb->s_blocksize_bits	= PAGE_SHIFT;
	sb->s_magic		= RAMFS_MAGIC;
	sb->s_op		= &ramfs_ops;
	sb->s_time_gran		= 1;

	inode = ramfs_get_inode(sb, NULL, S_IFDIR | fsi->mount_opts.mode, 0);
	sb->s_root = d_make_root(inode);
	if (!sb->s_root)
		return -ENOMEM;

	return 0;
}

static int ramfs_get_tree(struct fs_context *fc)
{
	return get_tree_nodev(fc, ramfs_fill_super);
}

static void ramfs_free_fc(struct fs_context *fc)

