/* 학습 해설
 * MINIX·파일시스템 형식과 구현 계약
 * 작은 전통 파일시스템에서 inode bitmap·zone bitmap·directory format이 version과 함께 어떻게 연결되는지 볼 수 있습니다.
 * Minix mount는 superblock을 읽고 magic으로 V1/V2/V3와 이름·directory entry 크기를 선택합니다. Imap·zmap block을 읽어 inode·data zone 사용 상태를 관리하고 bit 0을 예약합니다. Bitmap이 표현해야 할 자원보다 부족하면 mount를 거부합니다. Root inode를 얻고 writable 이전 version은 clean 상태 bit를 지우며 오류 경로는 map·buffer를 정리합니다.
 * 격리된 VM에서 새 실습용 Minix 이미지를 read-only로 관찰하고 version·block size·inode/zone map을 비교합니다. 실제 저장장치를 재포맷하지 않고 image의 layout·fsck clean 상태와 mount 결과를 연결합니다.
 */
static int minix_fill_super(struct super_block *s, struct fs_context *fc)
{
	struct buffer_head *bh;
	struct buffer_head **map;
	struct minix_super_block *ms;
	struct minix3_super_block *m3s = NULL;
	unsigned long i, block;
	struct inode *root_inode;
	struct minix_sb_info *sbi;
	int ret = -EINVAL;
	int silent = fc->sb_flags & SB_SILENT;

	sbi = kzalloc(sizeof(struct minix_sb_info), GFP_KERNEL);
	if (!sbi)
		return -ENOMEM;
	s->s_fs_info = sbi;

	BUILD_BUG_ON(32 != sizeof (struct minix_inode));
	BUILD_BUG_ON(64 != sizeof(struct minix2_inode));

	if (!sb_set_blocksize(s, BLOCK_SIZE))
		goto out_bad_hblock;

	if (!(bh = sb_bread(s, 1)))
		goto out_bad_sb;

