/* 학습 해설
 * EXT2·파일시스템 형식과 구현 계약
 * Ext2의 전통 block pointer 구조는 file logical block을 direct·single·double·triple indirect 경로로 나눕니다.
 * Ext2 inode는 12 direct pointer와 single/double/triple indirect root를 사용합니다. Block 안 pointer 수 N=blocksize/4에 따라 single은 N, double은 N², triple은 N³ block을 연결합니다. Block_to_path는 이전 영역 크기를 빼며 offsets 배열을 구성하고 shift/mask로 각 level index를 구합니다. 이 함수는 경로 계산이며 실제 disk read·allocation은 별도입니다.
 * 격리된 Ext2 실습 image에서 block size·file logical block·pointer path를 확인합니다. Ext4 extent format이나 journal이 이 driver에 자동 존재한다고 가정하지 않고 get_branch·allocation·truncation 동기화를 연결합니다.
 */
static int ext2_block_to_path(struct inode *inode,
			long i_block, int offsets[4], int *boundary)
{
	int ptrs = EXT2_ADDR_PER_BLOCK(inode->i_sb);
	int ptrs_bits = EXT2_ADDR_PER_BLOCK_BITS(inode->i_sb);
	const long direct_blocks = EXT2_NDIR_BLOCKS,
		indirect_blocks = ptrs,
		double_blocks = (1 << (ptrs_bits * 2));
	int n = 0;
	int final = 0;

	if (i_block < 0) {
		ext2_msg(inode->i_sb, KERN_WARNING,
			"warning: %s: block < 0", __func__);
	} else if (i_block < direct_blocks) {
		offsets[n++] = i_block;
		final = direct_blocks;
	} else if ( (i_block -= direct_blocks) < indirect_blocks) {
		offsets[n++] = EXT2_IND_BLOCK;
		offsets[n++] = i_block;
		final = ptrs;
	} else if ((i_block -= indirect_blocks) < double_blocks) {
		offsets[n++] = EXT2_DIND_BLOCK;
		offsets[n++] = i_block >> ptrs_bits;
		offsets[n++] = i_block & (ptrs - 1);
		final = ptrs;

