/* 학습 해설
 * VBOXSF·파일시스템 형식과 구현 계약
 * VirtualBox shared folder는 host에서 내용이 바뀔 수 있어 guest inode cache와 page cache의 유효성을 다시 확인해야 합니다.
 * Vboxsf revalidate는 positive dentry인지 확인하고 force_restat가 없으며 TTL 안이면 cache를 사용합니다. 다시 stat한 결과로 inode를 갱신하고 이전보다 mtime이 증가하면 page cache를 invalidate합니다. Host shared-folder protocol을 통해 metadata를 가져오며 이 검사만으로 모든 동시 변경의 완전한 snapshot을 약속하지는 않습니다.
 * 격리된 VirtualBox guest에서 share·ttl·guest additions·host 변경과 cache를 관찰합니다. Kernel 모듈 지원·host permission과 guest 표시 permission을 구분하고 timestamp 해상도·TTL·mtime 비교 조건을 확인합니다.
 */
int vboxsf_inode_revalidate(struct dentry *dentry)
{
	struct vboxsf_sbi *sbi;
	struct vboxsf_inode *sf_i;
	struct shfl_fsobjinfo info;
	struct timespec64 mtime, prev_mtime;
	struct inode *inode;
	int err;

	if (!dentry || !d_really_is_positive(dentry))
		return -EINVAL;

	inode = d_inode(dentry);
	prev_mtime = inode_get_mtime(inode);
	sf_i = VBOXSF_I(inode);
	sbi = VBOXSF_SBI(dentry->d_sb);
	if (!sf_i->force_restat) {
		if (time_before(jiffies, dentry->d_time + sbi->o.ttl))
			return 0;
	}

	err = vboxsf_stat_dentry(dentry, &info);
	if (err)
		return err;

	dentry->d_time = jiffies;

