/* 학습 해설
 * UDF·파일시스템 형식과 구현 계약
 * UDF logical volume은 partition reference와 여러 mapping 종류를 통해 optical storage의 physical block으로 연결됩니다.
 * UDF는 tagged logical volume descriptor와 map table 길이를 검증한 뒤 partition map별 변환 함수를 선택합니다. Type 1은 기본 map, type 2는 virtual VAT·sparable·metadata variant를 식별합니다. Virtual map은 revision suffix에 따라 1.5/2.0 helper가 다르고 metadata map은 file·mirror·bitmap 위치를 저장합니다. Fileset 주소는 logical block과 partition reference 쌍입니다.
 * 격리된 UDF image에서 revision·partition map·VAT·metadata mirror·tag checksum/CRC를 확인합니다. Logical volume과 물리 partition을 같은 좌표로 취급하지 않고 map 종류와 지원 revision을 연결합니다.
 */
static int udf_load_logicalvol(struct super_block *sb, sector_t block,
			       struct kernel_lb_addr *fileset)
{
	struct logicalVolDesc *lvd;
	int i, offset;
	uint8_t type;
	struct udf_sb_info *sbi = UDF_SB(sb);
	struct genericPartitionMap *gpm;
	uint16_t ident;
	struct buffer_head *bh;
	unsigned int table_len;
	int ret;

	bh = udf_read_tagged(sb, block, block, &ident);
	if (!bh)
		return -EAGAIN;
	BUG_ON(ident != TAG_IDENT_LVD);
	lvd = (struct logicalVolDesc *)bh->b_data;
	table_len = le32_to_cpu(lvd->mapTableLength);
	if (table_len > sb->s_blocksize - sizeof(*lvd)) {
		udf_err(sb, "error loading logical volume descriptor: "
			"Partition table too long (%u > %lu)\n", table_len,
			sb->s_blocksize - sizeof(*lvd));
		ret = -EIO;
		goto out_bh;
	}

