/* 학습 해설
 * TC Cgroup·Task Classid와 Packet 분류
 * 프로세스 소속 group에서 얻은 classid로 packet을 classful qdisc에 연결하는 경로를 볼 수 있습니다.
 * Cgroup classifier는 task_get_classid(skb)로 classid를 얻습니다. Head가 없거나 classid가 0이거나 ematch가 실패하면 -1입니다. 성공하면 result classid를 설정하고 action을 실행합니다. Net_cls 계열 설정과 socket/task context·kernel config에 따라 classid 출처가 달라질 수 있어 모든 cgroup v2 환경에서 자동 작동한다고 보장되지 않습니다.
 * 격리된 namespace/cgroup 실습에서 net_cls 지원·hierarchy·socket 생성 시점과 tc class를 연결합니다. Cgroup membership·network namespace·packet metadata·CPU scheduling group을 같은 객체로 취급하지 않습니다.
 */
TC_INDIRECT_SCOPE int cls_cgroup_classify(struct sk_buff *skb,
					  const struct tcf_proto *tp,
					  struct tcf_result *res)
{
	struct cls_cgroup_head *head = rcu_dereference_bh(tp->root);
	u32 classid = task_get_classid(skb);

	if (unlikely(!head))
		return -1;
	if (!classid)
		return -1;
	if (!tcf_em_tree_match(skb, &head->ematches, NULL))
		return -1;

	res->classid = classid;
	res->class = 0;

	return tcf_exts_exec(skb, &head->exts, res);
}

